29	  unfoldUnitLines,
30	  versionProbeSafe,
31	  type HomeExpansionHost,
32	  type UnitExecHost,
33	} from "../worker/migrate-real.ts";
34	import { SCAN_SCRIPT } from "../worker/migrate-detect.ts";
35	import { isAbandonedMigration, MIGRATION_ABANDON_MS } from "../worker/migrate.ts";
36	import { execFileSync } from "node:child_process";
37	import { mkdirSync, mkdtempSync, writeFileSync, rmSync } from "node:fs";
38	import { tmpdir } from "node:os";
