41	/**
42	 * The migration verification gate — the pure decision logic that stands between
43	 * "the copy finished" and telling a customer their move is done. Every case here
44	 * is a real field incident; `worker/migrate-real.ts` names this file twice (at
45	 * `judgeMigrationOutcome` and at `UnitExecHost`) as the place that keeps them from
46	 * recurring.
47	 *
48	 * Deterministic: no SSH, no network, no clock. `preflightUnitExecs` is driven
49	 * through its `UnitExecHost` seam with an in-memory fake host.
50	 */
51	
52	/* ------------------------------------------------------------------ *
53	 * 1. A stock web-server page is NOT the customer's site
54	 *    Incident 2026-07-25: the run reported the customer's main site as serving.
55	 *    The browser showed a cert warning and then the Apache2 Debian Default Page —
56	 *    apache2 had been re-enabled from the source and was answering on a port our
57	 *    generated nginx config was supposed to own. Every placeholder answers 200,
58	 *    which is why "make a request and check the status" passed for a dead site.
59	 * ------------------------------------------------------------------ */
60	
61	const REAL_PAGE =
62	  "<!doctype html><html><head><title>Studio Nexis</title></head><body>" +
63	  "<h1>Studio Nexis</h1><p>We build things. Contact us for a quote.</p></body></html>";
64	
65	test("a 200 carrying a distro default page is not 'serving'", () => {
66	  const apacheDebian =
67	    '<!DOCTYPE html><html><head><title>Apache2 Debian Default Page: It works</title></head>' +
68	    "<body><h1>Apache2 Debian Default Page</h1><p>This is the default welcome page…</p></body></html>";
69	  const reason = defaultPageReason("200", apacheDebian);
70	  assert.match(reason, /Apache2 Debian default page/);
71	  assert.match(reason, /not your site/);
72	
73	  assert.match(defaultPageReason("200", "<h1>Welcome to nginx!</h1>" + "x".repeat(200)), /Welcome to nginx/);
74	  assert.match(
75	    defaultPageReason("200", "<html><body><h1>It works!</h1></body></html>"),
76	    /It works!/,
77	    "the classic /var/www/html/index.html",
78	  );
79	  assert.match(
80	    defaultPageReason("200", "<title>Apache HTTP Server Test Page</title>" + "y".repeat(200)),
81	    /stock Apache test page/,
82	  );
83	  assert.equal(DEFAULT_PAGE_MARKERS.length, 5, "five known placeholders; add a test with the sixth");
84	});
85	
86	test("a default page split across a newline still matches (probeBody keeps newlines)", () => {
87	  // Regression guard on probeBody: the earlier `clean()` stripped ALL control
88	  // characters including newlines, gluing "Apache2 Debian Default\nPage" into
89	  // "DefaultPage" and making every marker unmatchable.
90	  const raw = "<h1>Apache2 Debian Default\nPage</h1>\x00\x07<p>default welcome</p>";
91	  const body = probeBody(raw);
92	  assert.ok(body.includes("\n"), "newlines survive");
93	  assert.ok(!body.includes("\x00"), "other control characters become spaces");
94	  assert.match(defaultPageReason("200", body), /Apache2 Debian default page/);
95	});
96	
97	test("a real page is never flagged, even when its copy contains the words 'it works'", () => {
98	  assert.equal(defaultPageReason("200", REAL_PAGE), "");
99	  const prose = "<html><body><h2>Our process</h2><p>Tell us what you need and it works! Really.</p>" + "z".repeat(120) + "</body></html>";
100	  assert.equal(defaultPageReason("200", prose), "", "the marker is anchored on <h1>, not on the phrase");
101	});
102	
103	test("an empty 200 is a dead vhost, but a short API response is not", () => {
104	  const empty = defaultPageReason("200", "   \n  ");
105	  assert.match(empty, /empty page/);
106	  assert.match(empty, /is not there/);
107	  assert.equal(defaultPageReason("200", '{"ok":true}'), "", "a JSON API answering correctly");
108	  assert.equal(defaultPageReason("200", "[]"), "", "a JSON array");
109	  assert.equal(defaultPageReason("200", '<?xml version="1.0"?><rss/>'), "", "a feed");
110	  // A JavaScript app's HTML is just a mount point — almost no visible text, but
111	  // comfortably above the byte floor, so it must never be called dark.
112	  const nextShell = '<div id="root"></div><script src="/_next/static/chunks/main.js" defer></script>';
113	  assert.ok(nextShell.trim().length > NEAR_EMPTY_BODY_BYTES);
114	  assert.equal(defaultPageReason("200", nextShell), "");
115	  // The floor is measured on the TRIMMED body: whitespace padding is not content.
116	  assert.match(defaultPageReason("200", "<div id=root></div>".padEnd(400, " ")), /empty page \(19 bytes\)/);
117	});
118	
119	test("content is only judged on a 2xx — a redirect or 404 already proves the vhost matched", () => {
120	  for (const code of ["301", "302", "401", "403", "404"]) {
121	    assert.equal(defaultPageReason(code, ""), "", `${code} with an empty body is not a content failure`);
122	    assert.equal(defaultPageReason(code, "<h1>Welcome to nginx!</h1>"), "", `${code} is not judged on content`);
123	  }
124	  assert.equal(defaultPageReason("000", ""), "", "a connection failure is handled by isServing, not here");
125	});
126	
127	test("isServing accepts any answered status and rejects dead ports and 5xx", () => {
128	  for (const code of ["200", "204", "301", "302", "401", "403", "404", "418"]) {
129	    assert.equal(isServing(code), true, code);
130	  }
131	  for (const code of ["000", "500", "502", "503", "504", "", "abc"]) {
132	    assert.equal(isServing(code), false, code);
133	  }
134	});
