136	/* ------------------------------------------------------------------ *
137	 * 2. Wildcard certificates cover ONE label
138	 *    Incident 2026-07-25: studionexis.com was served nexis.revsports.ca's
139	 *    certificate, so every visitor got ERR_CERT_COMMON_NAME_INVALID — and the run
140	 *    reported the domain as serving, because the probe used -k.
141	 * ------------------------------------------------------------------ */
142	
143	test("*.example.com covers exactly one label — not two, and not the bare domain", () => {
144	  assert.equal(certCoversName(["*.example.com"], "www.example.com"), true);
145	  assert.equal(certCoversName(["*.example.com"], "api.example.com"), true);
146	  assert.equal(certCoversName(["*.example.com"], "a.b.example.com"), false, "two labels are NOT covered");
147	  assert.equal(certCoversName(["*.example.com"], "example.com"), false, "the apex needs its own SAN");
148	  assert.equal(certCoversName(["*.example.com", "example.com"], "example.com"), true);
149	});
150	
151	test("a certificate for another site never counts as covering this one", () => {
152	  assert.equal(certCoversName(["nexis.revsports.ca", "*.revsports.ca"], "studionexis.com"), false);
153	  assert.equal(certCoversName([], "studionexis.com"), false, "no names known => not covered");
154	  assert.equal(certCoversName(["*.com"], "studionexis.com"), true, "single-label wildcard math is still one label");
155	  assert.equal(certCoversName(["*.studionexis.com"], "studionexis.com.evil.test"), false);
156	});
157	
158	test("case and a trailing dot do not change coverage", () => {
159	  assert.equal(certCoversName(["studionexis.com"], "StudioNexis.COM"), true);
160	  assert.equal(certCoversName(["studionexis.com"], "studionexis.com."), true);
161	  assert.equal(certCoversName(["*.studionexis.com"], "WWW.StudioNexis.com."), true);
162	});
