164	/* ------------------------------------------------------------------ *
165	 * 3. ExecStart parsing — field note #13, which recurred as #25
166	 *    nexis-next.service carried
167	 *      ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105
168	 *    The source had a hand-installed Node at /usr/local/bin/node; the target has
169	 *    apt's at /usr/bin/node and NOTHING at /usr/local/bin/node. systemd failed the
170	 *    exec 203/EXEC, the unit crash-looped 78 times, and the migration reported
171	 *    SUCCESS.
172	 * ------------------------------------------------------------------ */
173	
174	test("the exact unit from the incident yields its absolute interpreter path", () => {
175	  const unit = [
176	    "[Unit]",
177	    "Description=nexis-next",
178	    "[Service]",
179	    "WorkingDirectory=/opt/nexis",
180	    "ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105",
181	    "Restart=always",
182	    "[Install]",
183	    "WantedBy=multi-user.target",
184	  ].join("\n");
185	  assert.deepEqual(parseUnitExecPaths(unit), [{ directive: "ExecStart", path: "/usr/local/bin/node" }]);
186	});
187	
188	test("systemd's -, @, +, ! and !! prefixes are stripped in any combination", () => {
189	  const cases = ["-", "@", "+", "!", "!!", "-@", "+!", "!!-", "@+!"];
190	  for (const prefix of cases) {
191	    assert.deepEqual(
192	      parseUnitExecPaths(`ExecStart=${prefix}/usr/bin/sshd -D`),
193	      [{ directive: "ExecStart", path: "/usr/bin/sshd" }],
194	      `prefix ${prefix}`,
195	    );
196	  }
197	  // With whitespace after the prefix, as systemd also allows.
198	  assert.deepEqual(parseUnitExecPaths("ExecStart=- /usr/bin/sshd"), [{ directive: "ExecStart", path: "/usr/bin/sshd" }]);
199	});
200	
201	test("quoted commands are unquoted; a path with a space is skipped as unresolvable", () => {
202	  assert.deepEqual(parseUnitExecPaths('ExecStart="/usr/bin/python3" /srv/app/main.py'), [
203	    { directive: "ExecStart", path: "/usr/bin/python3" },
204	  ]);
205	  assert.deepEqual(parseUnitExecPaths("ExecStart='/usr/bin/php8.2' -f /srv/cron.php"), [
206	    { directive: "ExecStart", path: "/usr/bin/php8.2" },
207	  ]);
208	  // Spaces are outside the shell-inert allowlist, so the path is reported to
209	  // nobody rather than being interpolated into a command.
210	  assert.deepEqual(parseUnitExecPaths('ExecStart="/opt/my app/bin/run" --flag'), []);
211	});
212	
213	test("line continuations are folded before the command is read", () => {
214	  // Read line-at-a-time, the first line's command is empty and the check is
215	  // skipped entirely — the unit then gets enabled unverified.
216	  const unit = ["[Service]", "ExecStart=\\", "  /usr/local/bin/node \\", "  /opt/nexis/server.js --port 3105"].join("\n");
217	  assert.deepEqual(unfoldUnitLines(unit), [
218	    "[Service]",
219	    "ExecStart=   /usr/local/bin/node    /opt/nexis/server.js --port 3105",
220	  ]);
221	  assert.deepEqual(parseUnitExecPaths(unit), [{ directive: "ExecStart", path: "/usr/local/bin/node" }]);
222	  // CRLF unit files (copied off a Windows-edited source) fold identically.
223	  assert.deepEqual(parseUnitExecPaths("ExecStart=\\\r\n  /usr/bin/node /app/x.js\r\n"), [
224	    { directive: "ExecStart", path: "/usr/bin/node" },
225	  ]);
226	});
227	
228	test("% specifiers, PATH-relative commands and list resets are all skipped", () => {
229	  assert.deepEqual(parseUnitExecPaths("ExecStart=/usr/bin/%i --serve"), [], "%i can only be resolved by systemd");
230	  assert.deepEqual(parseUnitExecPaths("ExecStart=/opt/app/%n/run"), []);
231	  assert.deepEqual(parseUnitExecPaths("ExecStart=node /srv/server.js"), [], "PATH-resolved: not ours to check");
232	  assert.deepEqual(parseUnitExecPaths("ExecStart=env NODE_ENV=production node app.js"), []);
233	  assert.deepEqual(parseUnitExecPaths("ExecStart="), [], "an empty assignment is systemd's list reset");
234	  assert.deepEqual(parseUnitExecPaths("ExecStart=  "), []);
235	  assert.deepEqual(parseUnitExecPaths("ExecStart=-"), [], "a bare prefix with no command");
236	  assert.deepEqual(parseUnitExecPaths("ExecStart=../../bin/node app.js"), [], "relative paths are not absolute");
237	  assert.deepEqual(parseUnitExecPaths("ExecStart=/usr/bin/../bin/node"), [], ".. is rejected, never normalised");
238	});
239	
240	test("only the three start directives are collected, and duplicates collapse", () => {
241	  const unit = [
242	    "[Service]",
243	    "ExecStartPre=/usr/bin/mkdir -p /run/app",
244	    "ExecStart=/usr/bin/node /srv/app.js",
245	    "ExecStartPost=/usr/bin/systemd-notify --ready",
246	    "ExecReload=/bin/kill -HUP $MAINPID",
247	    "ExecStop=/usr/bin/node /srv/shutdown.js",
248	    "ExecStopPost=/usr/bin/rm -f /run/app/pid",
249	  ].join("\n");
250	  assert.deepEqual(parseUnitExecPaths(unit), [
251	    { directive: "ExecStartPre", path: "/usr/bin/mkdir" },
252	    { directive: "ExecStart", path: "/usr/bin/node" },
253	    { directive: "ExecStartPost", path: "/usr/bin/systemd-notify" },
254	  ]);
255	
256	  const dupes = ["ExecStartPre=/usr/bin/node /a.js", "ExecStartPre=/usr/bin/node /b.js", "ExecStart=/usr/bin/node /c.js"].join("\n");
257	  assert.deepEqual(parseUnitExecPaths(dupes), [
258	    { directive: "ExecStartPre", path: "/usr/bin/node" },
259	    { directive: "ExecStart", path: "/usr/bin/node" },
260	  ], "same directive + same path once; a different directive is its own check");
261	});
262	
263	test("a pathological unit cannot make the pre-flight unbounded", () => {
264	  const many = Array.from({ length: 40 }, (_, i) => `ExecStartPre=/usr/bin/tool${i}`).join("\n");
265	  assert.equal(parseUnitExecPaths(many).length, 12, "capped at 12 exec refs");
266	  assert.deepEqual(parseUnitExecPaths(""), []);
267	  assert.deepEqual(parseUnitExecPaths("[Unit]\nDescription=nothing to run here\n"), []);
268	});
