274	type FakeHostOpts = {
275	  unitText: string;
276	  /** Absolute paths that exist AND are executable on the target. */
277	  executable?: string[];
278	  /** Absolute paths that exist but are not executable. */
279	  presentNotExecutable?: string[];
280	  /** basename -> what `command -v` answers. */
281	  which?: Record<string, string>;
282	  /** absolute path -> what `<path> --version` prints on the TARGET. */
283	  version?: Record<string, string>;
284	  /** absolute path -> what `<path> --version` printed on the SOURCE. */
285	  sourceVersion?: Record<string, string>;
286	  /** Absolute paths that exist on the SOURCE box. */
287	  onSource?: string[];
288	  /** Make symlink creation fail (read-only /usr, race, …). */
289	  symlinkFails?: boolean;
290	  copyFails?: boolean;
291	};
292	
293	function fakeHost(opts: FakeHostOpts) {
294	  const executable = new Set(opts.executable ?? []);
295	  const present = new Set([...(opts.presentNotExecutable ?? []), ...executable]);
296	  const calls: string[] = [];
297	  const host: UnitExecHost = {
298	    readUnitFile: async () => opts.unitText,
299	    isExecutable: async (p) => executable.has(p),
300	    exists: async (p) => present.has(p),
301	    whichSameName: async (base) => opts.which?.[base] ?? "",
302	    versionOf: async (p) => opts.version?.[p] ?? "",
303	    versionOnSource: async (p) => opts.sourceVersion?.[p] ?? "",
304	    symlink: async ({ target, linkPath }) => {
305	      calls.push(`symlink ${linkPath} -> ${target}`);
306	      if (opts.symlinkFails) return false;
307	      executable.add(linkPath);
308	      present.add(linkPath);
309	      return true;
310	    },
311	  };
312	  const said: string[] = [];
313	  return {
314	    host,
315	    calls,
316	    said,
317	    args: {
318	      host,
319	      unit: "nexis-next",
320	      unitFile: "/etc/systemd/system/nexis-next.service",
321	      existsOnSource: async (p: string) => (opts.onSource ?? []).includes(p),
322	      copyFromSource: async (p: string) => {
323	        calls.push(`copy ${p}`);
324	        if (opts.copyFails) return false;
325	        executable.add(p);
326	        present.add(p);
327	        return true;
328	      },
329	      say: async (line: string) => {
330	        said.push(line);
331	      },
332	    },
333	  };
334	}
