645	test("the source inventory script is valid POSIX shell, as root and via sudo", () => {
646	  for (const priv of ["", "sudo -n "]) {
647	    const text = srcInventoryScript(priv);
648	    const file = join(tmpdir(), `nxeon-inv-${priv ? "sudo" : "root"}-${process.pid}.sh`);
649	    writeFileSync(file, text);
650	    try {
651	      // `sh -n` parses without executing: nothing here touches the machine.
652	      execFileSync("sh", ["-n", file], { stdio: "pipe" });
653	      execFileSync("dash", ["-n", file], { stdio: "pipe" });
654	    } finally {
655	      rmSync(file, { force: true });
656	    }
657	  }
658	});
