687	/* ------------------------------------------------------------------ *
688	 * 7. Row structure survives sanitisation
689	 *
690	 * The 2026-07-26 rehearsal — the first time this engine was ever run end to end
691	 * against a purpose-built messy source — found the same bug in six places at
692	 * once. `clean()` strips every control character INCLUDING \n and \t, and six
693	 * verification paths called it and then split the result on \n or looked for a
694	 * \t. Each one silently parsed a single glued row, and each one had surrounding
695	 * code that reported a conclusion on the strength of that empty parse.
696	 *
697	 * These are not six typos. They are one lesson (already written down in this
698	 * codebase, for `probeBody`, and applied nowhere else) that had to be re-learned
699	 * by running the thing. Every parser below is now a named function so it can be
700	 * given the exact bytes the real command produced.
701	 * ------------------------------------------------------------------ */
702	
703	test("cleanRows keeps rows apart while still removing control characters", () => {
704	  // The distinguishing property: `clean` would return ONE element here.
705	  const rows = cleanRows("alpha\nbeta\tgamma\n\x00delta\x07\n\n  \n", 4096);
706	  assert.deepEqual(rows, ["alpha", "beta\tgamma", "delta"]);
707	  assert.ok(rows.length > 1, "the whole point: a multi-row output stays multi-row");
708	  assert.ok(rows[1].includes("\t"), "tabs survive — column parsers depend on them");
709	  assert.ok(!rows.some((r) => /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(r)), "other control characters are still stripped");
710	  assert.deepEqual(cleanRows("", 10), [], "empty output is no rows, not one empty row");
711	  assert.deepEqual(cleanRows(null, 10), []);
712	});
