714	test("every TCP port is read from ss, not just the last one on the box", () => {
715	  // Incident: `clean(stdout).split("\n")` glued ss's output into one string and
716	  // the `$`-anchored /:(\d{1,5})$/ then matched ONLY the final port. `listening`
717	  // held one port at random. `appPorts` is filtered through this set and is the
718	  // fallback upstream for synthesising a vhost — so a container app that was up
719	  // and bound got no vhost, and the customer's domain served the stock distro
720	  // page. This is the exact `ss -lnt | awk '{print $4}'` output from the run.
721	  const ss = "Local Address:Port\n0.0.0.0:22\n0.0.0.0:80\n127.0.0.1:3105\n[::]:443\n127.0.0.1:3306\n";
722	  const ports = parseListeningPorts(ss);
723	  assert.equal(ports.size, 5, "five bound ports, not one");
724	  for (const p of [22, 80, 443, 3105, 3306]) assert.ok(ports.has(p), `port ${p} was found`);
725	  assert.ok(!ports.has(0));
726	  // The header row carries no port and must not become one.
727	  assert.deepEqual([...parseListeningPorts("Local Address:Port\n")], []);
728	  // Out-of-range never enters the set.
729	  assert.ok(!parseListeningPorts("0.0.0.0:99999\n").has(99999));
730	});
