4057	export async function issueMigrationCertificates(input: MigrationTlsInput): Promise<MigrationTlsResult> {
4058	  const { target, migrationId } = input;
4059	  if (!target) return { secured: [], pending: [], error: "target server row not found" };
4060	  const work = migrationWorkDir(migrationId);
4061	  const { conn, sftp } = await connectTarget(target);
4062	  const say = async (line: string) => {
4063	    if (input.report) await input.report(50, "Securing your site…", line);
4064	  };
4065	  try {
4066	    const spec = await readSiteSpec(conn, work);
4067	    // `permanent`: this run never published a site config, so no amount of
4068	    // waiting or DNS movement will make one appear. The post-cutover sweep uses
4069	    // this to stop retrying — without it, a migration that published nothing is
4070	    // re-attempted every 6 hours for a fortnight and notifies the customer each
4071	    // time about HTTPS for sites that do not exist.
4072	    if (!spec) {
4073	      return {
4074	        secured: [],
4075	        pending: [],
4076	        error: "this migration did not publish a site configuration we can secure",
4077	        permanent: true,
4078	      };
4079	    }
4080	    // Fold in hostnames the platform already knows, attached to the site whose
4081	    // names they share a suffix with (else the first site).
4082	    for (const raw of (input.extraDomains ?? []).slice(0, 20)) {
4083	      const d = normalizeDomain(raw);
4084	      if (!d || spec.sites.some((s) => s.names.includes(d))) continue;
4085	      const holder = spec.sites.find((s) => s.names.some((n) => d.endsWith(`.${n}`) || n.endsWith(`.${d}`))) ?? spec.sites[0];
4086	      if (holder && holder.names.length < 12) holder.names.push(d);
4087	    }
4088	    let targetIp = clean(target.dedicatedIp?.address ?? "", 64);
4089	    if (!IPV4_RE.test(targetIp)) {
4090	      targetIp = clean((await sh(conn, `hostname -I 2>/dev/null | awk '{print $1}'`)).stdout, 64);
4091	      if (!IPV4_RE.test(targetIp)) targetIp = "";
4092	    }
4093	    const hostWebUp = await shOk(conn, `systemctl is-active nginx >/dev/null 2>&1 || systemctl is-active apache2 >/dev/null 2>&1`);
4094	    return await secureSites({
4095	      conn,
4096	      sftp,
4097	      work,
4098	      spec,
4099	      targetIp,
4100	      email: clean(input.acmeEmail ?? "", 190),
4101	      cloudflareToken: input.cloudflareToken,
4102	      webOwnedByContainer: !hostWebUp,
4103	      say,
4104	    });
4105	  } catch (e: any) {
4106	    return { secured: [], pending: [], error: clean(e?.message ?? e, 300) };
4107	  } finally {
4108	    await sh(conn, `shred -u ${work}/cf-dns.ini 2>/dev/null || rm -f ${work}/cf-dns.ini`).catch(() => {});
4109	    try {
4110	      conn.end();
4111	    } catch {
4112	      /* best-effort */
4113	    }
4114	  }
4115	}
