233	/**
234	 * POST-DNS-CUTOVER certificate pass.
235	 *
236	 * HTTP-01 cannot validate a hostname that still resolves to the OLD server —
237	 * that is a property of the protocol, not a bug — so at migration time every
238	 * name whose DNS has not moved comes back as a named pending item. This is the
239	 * second half: run the same ladder again once the record is live.
240	 *
241	 * `issueMigrationCertificates` was written for exactly this and, until now, had
242	 * ZERO callers, so TLS was never retried after cutover and the customer's first
243	 * HTTPS visit was a certificate warning.
244	 *
245	 * Deliberate properties:
246	 *   - It copies NOTHING. It re-reads the `sites.json` the original run persisted
247	 *     on the target, walks the ladder, and reloads the vhost. A migration is
248	 *     never re-run by this path, so an accidental/duplicate enqueue cannot
249	 *     re-transfer a customer's data over the top of itself.
250	 *   - It is idempotent: certbot's `--keep-until-expiring` makes it a no-op once
251	 *     a certificate is in place, so it is safe to enqueue repeatedly.
252	 *   - It does NOT touch `Migration.status`. The terminal outcome belongs to the
253	 *     run that measured it; a certificate pass has not re-probed the sites and
254	 *     must not silently upgrade `COMPLETED_WITH_ISSUES` to `DONE`.
255	 *   - It never touches the SOURCE server.
256	 *
257	 * Enqueue it with:
258	 *   db.job.create({ data: { type: "MIGRATE", payload: { migrationId, phase: "tls" } } })
259	 */
260	async function runPostCutoverTls(
261	  migration: Awaited<ReturnType<typeof loadMigration>>,
262	  items: MigrationItems
263	): Promise<void> {
264	  const target = migration.server;
265	  const targetName = target ? target.label || target.hostname : "your server";
266	
267	  // Append-only log write: the migration row is already terminal and its status,
268	  // progress and step are the honest record of the run that produced them.
269	  let log = migration.log ?? null;
270	  const say = async (line: string) => {
271	    log = appendLog(log, line);
272	    await db.migration.update({ where: { id: migration.id }, data: { log } }).catch(() => {});
273	  };
274	
275	  if (!REAL_MIGRATION) {
276	    await say("HTTPS re-check skipped: real migration is not enabled on this platform, so no certificate was requested.");
277	    return;
278	  }
279	
280	  await say("Your DNS has moved — re-checking HTTPS and issuing any certificate that could not be issued before.");
281	  const tls = await resolveTlsInputs(migration.userId);
282	  if (tls.note) await say(`  ${tls.note}.`);
283	
284	  const res = await issueMigrationCertificates({
285	    target: target as any,
286	    migrationId: migration.id,
287	    extraDomains: tls.knownDomains,
288	    cloudflareToken: tls.cloudflareToken,
289	    acmeEmail: tls.acmeEmail,
290	    // Progress is meaningless for a post-cutover pass (the migration is over), so
291	    // the reporter is used purely as a log sink.
292	    report: async (_p, _s, line) => {
293	      await say(line);
294	    },
295	  });
296	
297	  if (res.error) {
298	    await say(`HTTPS re-check could not run: ${res.error}`);
299	    // A permanent condition — this run published no site configuration, so there
300	    // is nothing a later attempt could find. Settle it and stay silent: the
301	    // customer has no HTTPS problem to act on, because they have no published
302	    // sites. Notifying here would tell them about certificates for sites that do
303	    // not exist, once every retry, for a fortnight.
304	    if (res.permanent) {
305	      await db.migration
306	        .update({ where: { id: migration.id }, data: { items: { ...items, tlsSettled: true } as object } })
307	        .catch(() => {});
308	      return;
309	    }
310	    // Transient (SSH refused, target rebooting, certbot busy). Worth retrying —
311	    // but worth telling the customer only ONCE, not on every attempt.
312	    if (!(items as { tlsErrorNotified?: boolean }).tlsErrorNotified) {
313	      await db.migration
314	        .update({ where: { id: migration.id }, data: { items: { ...items, tlsErrorNotified: true } as object } })
315	        .catch(() => {});
316	      await notify(
317	        migration.userId,
318	        `Couldn't finish HTTPS on ${targetName}`,
319	        `${res.error} Your site keeps serving; only the certificate step is outstanding. We'll keep trying. Nothing on your old server was touched.`,
320	        "/dashboard/migrate"
321	      );
322	    }
323	    return;
324	  }
