329	  // this migration. Written into `items` (an existing JSON column) rather than a
330	  // new schema field: it is a fact about this run and belongs with the run's data.
331	  if (!pending.length) {
332	    await db.migration
333	      .update({ where: { id: migration.id }, data: { items: { ...items, tlsSettled: true } as object } })
334	      .catch(() => {});
335	  }
336	  if (secured.length) {
337	    await say(`HTTPS is live for ${secured.slice(0, 8).join(", ")}${secured.length > 8 ? ` (+${secured.length - 8} more)` : ""}.`);
