357	// ---- Abandoned migrations: the credential promise, kept on the crash path ---
358	/**
359	 * How long a migration may sit unfinished with NO live job before it is declared
360	 * abandoned. Generous: a real lift-and-shift of a large box legitimately runs for
361	 * a long time, and while it does its job row is QUEUED or RUNNING, which exempts
362	 * it from this entirely.
363	 */
364	export const MIGRATION_ABANDON_MS = 3 * 60 * 60_000;
365	
366	export type AbandonedMigrationInput = {
367	  status: string;
368	  finishedAt: Date | null;
369	  createdAt: Date;
370	  /** Is there a MIGRATE job for this migration still QUEUED or RUNNING? */
371	  hasLiveJob: boolean;
372	  now: number;
373	  maxAgeMs?: number;
374	};
375	
376	/**
377	 * Is this migration abandoned — unfinished, with nothing left that could ever
378	 * finish it?
379	 *
380	 * WHY THIS EXISTS. Two documents promise the same thing in the same words:
381	 * `lib/actions-migrate.ts` ("They are CLEARED by the worker the moment the
382	 * migration finishes — success or failure — so a completed Migration row never
383	 * retains usable credentials") and this file's own header. Both are true for
384	 * every path that reaches `runMigration`'s try/catch. Neither is true for the
385	 * path where the worker never reaches it:
386	 *
387	 *   worker crash / restart  →  `reapStuckJobs` (worker/index.ts) re-QUEUEs the
388	 *   MIGRATE job  →  it crashes again  →  `attempts >= MAX_ATTEMPTS`  →  the job
389	 *   is marked FAILED and handed to `reconcileFailedJob`, which handles RESIZE and
390	 *   DISK_EXPAND and returns immediately for everything else.
391	 *
392	 * Nothing then touches the Migration row again. It keeps `status: "RUNNING"`
393	 * forever — the customer's wizard polls a progress bar that will never move — and
394	 * it keeps `sourcePasswordEnc`, which is the ROOT SSH PASSWORD OF ANOTHER
395	 * PROVIDER'S LIVE SERVER, encrypted at rest but retained indefinitely for a run
396	 * that ended hours ago. "Cleared when the run ends, success or failure" has to
397	 * include the failure mode where nothing was there to clear it.
398	 *
399	 * Pure so the rule is testable without a database, a worker or a clock.
400	 */
401	export function isAbandonedMigration(m: AbandonedMigrationInput): boolean {
402	  if (m.finishedAt) return false;
403	  if (m.status !== "PENDING" && m.status !== "RUNNING") return false;
404	  // Something can still finish it — leave it alone however long it takes.
405	  if (m.hasLiveJob) return false;
406	  return m.now - m.createdAt.getTime() >= (m.maxAgeMs ?? MIGRATION_ABANDON_MS);
407	}
408	
409	/** What an abandoned migration is told, in the customer's words. */
410	const ABANDONED_MIGRATION_ERROR =
411	  "This migration stopped before it finished — the transfer was interrupted and nothing was left running that could pick it up. " +
412	  "Nothing on your old server was changed at any point, so it is still serving exactly as it was. Start the migration again when you're ready.";
413	
414	/**
415	 * Settle every abandoned migration: mark it FAILED and CLEAR its stored source
416	 * credentials. See `isAbandonedMigration` for the crash path this closes.
417	 *
418	 * Returns how many it settled, so the caller can log a number it actually
419	 * counted rather than an assurance.
420	 */
421	export async function reapAbandonedMigrations(): Promise<number> {
422	  const rows = await db.migration.findMany({
423	    where: { finishedAt: null, status: { in: ["PENDING", "RUNNING"] } },
424	    select: { id: true, userId: true, status: true, createdAt: true, finishedAt: true, items: true, log: true },
425	    orderBy: { createdAt: "asc" },
426	    take: 100,
427	  });
428	  if (!rows.length) return 0;
429	
430	  const now = Date.now();
431	  let reaped = 0;
432	  for (const m of rows) {
433	    const live = await db.job.findFirst({
434	      where: {
435	        type: "MIGRATE",
436	        status: { in: ["QUEUED", "RUNNING"] },
437	        payload: { path: ["migrationId"], equals: m.id },
438	      },
439	      select: { id: true },
440	    });
441	    if (!isAbandonedMigration({ status: m.status, finishedAt: m.finishedAt, createdAt: m.createdAt, hasLiveJob: !!live, now })) {
442	      continue;
443	    }
444	    const items = (m.items ?? {}) as MigrationItems;
445	    try {
446	      await db.migration.update({
447	        where: { id: m.id },
448	        data: {
449	          status: "FAILED",
450	          step: "Stopped before finishing",
451	          lastError: ABANDONED_MIGRATION_ERROR,
452	          finishedAt: new Date(),
453	          log: appendLog(m.log, `ERROR: ${ABANDONED_MIGRATION_ERROR}`),
454	        },
455	      });
456	      // The whole point of the sweep. Runs even if the status write above threw,
457	      // because retaining the credential is the worse of the two failures.
458	    } finally {
459	      await clearSecrets(m.id, items).catch((e) =>
460	        console.error(`[migrate] could not clear secrets for abandoned migration ${m.id}:`, e)
461	      );
462	    }
463	    reaped++;
464	    await notify(
465	      m.userId,
466	      "Migration stopped before it finished",
467	      ABANDONED_MIGRATION_ERROR,
468	      "/dashboard/migrate"
469	    );
470	  }
471	  if (reaped) console.log(`[migrate] settled ${reaped} abandoned migration(s) and cleared their stored source credentials`);
472	  return reaped;
473	}
