475	/** How long after a migration finishes we keep watching for the DNS cutover. */
476	const TLS_WATCH_DAYS = 14;
477	/** Minimum gap between certificate attempts for one migration. */
478	const TLS_RETRY_MS = 6 * 60 * 60_000;
479	/**
480	 * The longest one certificate pass may occupy the serial worker. Generous enough
481	 * for SSH plus certbot on a slow box, short enough that an unreachable target
482	 * cannot hold up provisioning.
483	 */
484	const TLS_PASS_TIMEOUT_MS = 4 * 60_000;
485	
486	/**
487	 * Enqueue the post-cutover certificate pass for migrations whose DNS may have
488	 * moved since they finished.
489	 *
490	 * WHY THIS EXISTS. `runPostCutoverTls` was written for exactly this job and had
491	 * exactly one enqueue line — **inside a comment**. So it was dead code, and a
492	 * customer who migrated, then pointed their DNS a day later, never got the
493	 * certificate that could not be issued during the run: their first HTTPS visit
494	 * was a browser warning, forever.
495	 *
496	 * That was bad on its own. It became worse on 2026-07-26, when the migration
497	 * report's cutover instructions were rewritten to tell the customer, in plain
498	 * words, that "Nxeon issues the certificate automatically within about 30 minutes
499	 * of the change, and nothing else is needed." That sentence was false the moment
500	 * it shipped. `sslSweep` does NOT cover this case — it walks `db.sslCertificate`
501	 * rows, and a migration never writes one. A promise the product does not keep is
502	 * the same defect as a success this engine did not verify, so the promise is made
503	 * true here rather than walked back in the copy.
504	 *
505	 * Safe to run repeatedly by construction: the pass copies nothing, never touches
506	 * the source server, never rewrites `Migration.status`, and certbot's
507	 * `--keep-until-expiring` makes an already-certified domain a no-op.
508	 */
509	export async function postCutoverTlsSweep(): Promise<void> {
510	  // Settled here rather than in its own registered sweep because this function is
511	  // the migration subsystem's ONLY periodic entry point (worker/index.ts calls it
512	  // every 30 minutes) and an unfinished migration holding a source root password
513	  // must not wait for a new registration to be plumbed in. It is wrapped so a
514	  // failure here can never stop the certificate pass that follows.
515	  await reapAbandonedMigrations().catch((e) => console.error("[migrate] abandoned-migration sweep failed:", e));
516	
517	  const since = new Date(Date.now() - TLS_WATCH_DAYS * 86_400_000);
518	  const runningServerIds = (
519	    await db.server.findMany({ where: { status: "RUNNING" }, select: { id: true } })
520	  ).map((s) => s.id);
521	  if (!runningServerIds.length) return;
522	
523	  const candidates = await db.migration.findMany({
524	    where: {
525	      status: { in: ["DONE", "COMPLETED_WITH_ISSUES"] },
526	      finishedAt: { gte: since },
527	      // SSH is the first thing this pass does. A server that is not running
528	      // cannot answer, and the attempt would occupy the strictly-serial worker
529	      // until the connection times out. `Migration.serverId` is a bare column
530	      // with no Prisma relation, so the running set is resolved separately.
531	      serverId: { in: runningServerIds },
532	    },
533	    select: { id: true, items: true, serverId: true },
534	    orderBy: { finishedAt: "desc" },
535	    take: 50,
536	  });
537	
538	  // ONE pass per target server, not per migration. A customer who retried a
539	  // migration three times has three rows pointing at the same box; certifying it
540	  // once certifies it for all of them, and the first live run queued four
541	  // redundant SSH sessions for a single server. Newest first, since that run's
542	  // published site config is the one on disk.
543	  const seenServers = new Set<string>();
544	
545	  for (const m of candidates) {
546	    // Already fully certified — a previous pass found nothing outstanding.
547	    if ((m.items as { tlsSettled?: boolean } | null)?.tlsSettled) continue;
548	    if (seenServers.has(m.serverId)) continue;
549	    seenServers.add(m.serverId);
550	
551	    // Don't stack attempts. A job still queued, or one tried recently, means the
552	    // answer is already on its way; certbot rate limits are real and shared.
553	    const recent = await db.job.findFirst({
554	      where: {
555	        type: "MIGRATE",
556	        createdAt: { gte: new Date(Date.now() - TLS_RETRY_MS) },
557	        payload: { path: ["migrationId"], equals: m.id },
558	      },
559	      select: { id: true },
560	    });
561	    if (recent) continue;
562	
563	    await db.job
564	      .create({ data: { type: "MIGRATE", payload: { migrationId: m.id, phase: "tls" } } })
565	      .catch((e) => console.error(`[migrate] could not enqueue TLS pass for ${m.id}:`, e));
566	  }
567	}
