569	export async function runMigration(job: Job): Promise<void> {
570	  const migration = await loadMigration(job);
571	  const items = (migration.items ?? {}) as MigrationItems;
572	  const paths = items.paths ?? [];
573	  const target = migration.server;
574	  const targetName = target ? target.label || target.hostname : "your server";
575	
576	  // The post-cutover certificate pass shares this handler (and therefore the
577	  // already-registered MIGRATE JobType) but is NOT a migration: it copies
578	  // nothing and must never fall through into the transfer below.
579	  if (((job.payload ?? {}) as MigratePayload).phase === "tls") {
580	    try {
581	      // HARD CEILING. This worker is strictly serial: whatever is in this
582	      // function is the only thing the platform is doing. The pass opens SSH to a
583	      // customer's box and runs certbot, and on the sweep's first live run a
584	      // single unresponsive target left the job RUNNING through two reap cycles
585	      // — with a new customer's provisioning job queued behind it. A background
586	      // nicety must never be able to stall the queue that provisions servers.
587	      await Promise.race([
588	        runPostCutoverTls(migration, items),
589	        new Promise<never>((_, reject) =>
590	          setTimeout(() => reject(new Error("post-cutover TLS pass exceeded its time budget")), TLS_PASS_TIMEOUT_MS)
591	        ),
592	      ]);
593	    } catch (e) {
594	      console.error(`[migrate] post-cutover TLS for ${migration.id} failed:`, e);
595	      // Swallowed on purpose: a failed certificate retry must not mark the
596	      // customer's finished migration as failed, and must not make the job loop
597	      // retry a phase that will keep failing for the same reason. The sweep will
598	      // come back to it on its own schedule.
599	    }
600	    return;
601	  }
602	
603	  // Fresh start (also lets a retried job re-enter cleanly).
604	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
605	  await db.migration.update({
606	    where: { id: migration.id },
607	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
