/**
 * Parse `text` as POSIX shell under BOTH `sh` and `dash` without executing it.
 * `sh -n` catches exactly the class the section-6 note describes: a quoting
 * mistake in the three-level nest (TS string → shell double quotes → embedded Go
 * template / sed / awk in single quotes) that passes tsc, lint and build and only
 * fails on a customer's live box mid-cutover.
 */
function shellParses(text: string, label: string): void {
  const file = join(tmpdir(), `nxeon-gen-${label}-${process.pid}.sh`);
  writeFileSync(file, text);
  try {
    execFileSync("sh", ["-n", file], { stdio: "pipe" });
    execFileSync("dash", ["-n", file], { stdio: "pipe" });
  } finally {
    rmSync(file, { force: true });
  }
}

